EVENTS_B64 = ''
KV_B64 = ''
SESSIONS_B64 = 'eNp1zUsKAjEQhOGrDFnLkE466S6vIiJm0gFF8IGKIHN3I4ILwV1BffCvnm5/3bnl4CCFa8yaW0lMscJHcCjQ0Hdq1S0GZ49TpyQIDIXEUXK/qT8Xux/PN9sc7ANIwdSB+qBZZF4M35AyTKei0iZwadiyKMGyoVHV2n5DCD6O5DV5jX9K/BakElKc1y96fDYX'


print('\n=== 2. Restauration de la base SQLite previa.db ===')
sqlite_path = os.path.join(DB_DIR, 'previa.db')
db_conn = sqlite3.connect(sqlite_path)
with db_conn:
    db_conn.execute('''
    CREATE TABLE IF NOT EXISTS kv_store (
        key TEXT PRIMARY KEY,
        value_json TEXT NOT NULL,
        mis_a_jour_le REAL NOT NULL
    );
    ''')
    db_conn.execute('''
    CREATE TABLE IF NOT EXISTS evenements_historique (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        camera_id TEXT NOT NULL,
        timestamp REAL NOT NULL,
        type_evenement TEXT NOT NULL,
        niveau TEXT NOT NULL,
        payload_json TEXT NOT NULL,
        statut TEXT NOT NULL DEFAULT 'nouveau',
        acquitte_par TEXT,
        acquitte_le REAL,
        commentaire TEXT
    );
    ''')
    db_conn.execute('''
    CREATE TABLE IF NOT EXISTS sessions_revoquees (
        token_hash TEXT PRIMARY KEY,
        revoque_le REAL NOT NULL
    );
    ''')
    
    # Inserer KV
    kv_data = json.loads(zlib.decompress(base64.b64decode(KV_B64)).decode('utf-8'))
    for row in kv_data:
        db_conn.execute("INSERT OR REPLACE INTO kv_store (key, value_json, mis_a_jour_le) VALUES (?, ?, ?)",
                        (row['key'], row['value_json'], row['mis_a_jour_le']))
    print(f'  [OK] {len(kv_data)} entrees inserees dans kv_store (personnel & faces ArcFace)')

    # Inserer Events
    events_data = json.loads(zlib.decompress(base64.b64decode(EVENTS_B64)).decode('utf-8'))
    for row in events_data:
        db_conn.execute('''
            INSERT OR REPLACE INTO evenements_historique 
            (id, camera_id, timestamp, type_evenement, niveau, payload_json, statut, acquitte_par, acquitte_le, commentaire)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        ''', (row['id'], row['camera_id'], row['timestamp'], row['type_evenement'], row['niveau'],
               row['payload_json'], row['statut'], row['acquitte_par'], row['acquitte_le'], row['commentaire']))
    print(f'  [OK] {len(events_data)} evenements historiques restaures')

    # Inserer Sessions
    sess_data = json.loads(zlib.decompress(base64.b64decode(SESSIONS_B64)).decode('utf-8'))
    for row in sess_data:
        db_conn.execute("INSERT OR REPLACE INTO sessions_revoquees (token_hash, revoque_le) VALUES (?, ?)",
                        (row['token_hash'], row['revoque_le']))
    print(f'  [OK] Sessions synchronisees')

